package org.apache.commons.lang.text;

import java.io.*;
import java.io.Reader;
import java.io.Writer;
import java.math.*;
import java.util.*;
import java.util.Collection;
import java.util.Iterator;
import java.util.List;
import org.apache.commons.lang.ArrayUtils;
import org.apache.commons.lang.SystemUtils;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for StrBuilder.indexOf(String str, int startIndex)
 * Aiming for maximum branch and line coverage.
 */
public class StrBuilder_indexOf_TriageGen2Test {

    @Test
    public void testIndexOf_NullString() {
        StrBuilder sb = new StrBuilder("hello");
        // if (str == null || startIndex >= size) return -1;
        Assert.assertEquals(-1, sb.indexOf(null, 0));
    }

    @Test
    public void testIndexOf_StartIndexGreaterThanSize() {
        StrBuilder sb = new StrBuilder("hello");
        // startIndex >= size returns -1
        Assert.assertEquals(-1, sb.indexOf("h", 5));
        Assert.assertEquals(-1, sb.indexOf("h", 10));
    }

    @Test
    public void testIndexOf_NegativeStartIndex() {
        StrBuilder sb = new StrBuilder("hello");
        // startIndex = (startIndex < 0 ? 0 : startIndex);
        // Should treat -1 as 0 and find "e" at index 1
        Assert.assertEquals(1, sb.indexOf("e", -1));
    }

    @Test
    public void testIndexOf_EmptyString() {
        StrBuilder sb = new StrBuilder("hello");
        // if (strLen == 0) return startIndex;
        Assert.assertEquals(2, sb.indexOf("", 2));
    }

    @Test
    public void testIndexOf_SingleCharString() {
        StrBuilder sb = new StrBuilder("hello");
        // if (strLen == 1) return indexOf(str.charAt(0), startIndex);
        // Note: This tests the internal char-based indexOf via the String-based one
        Assert.assertEquals(1, sb.indexOf("e", 0));
        Assert.assertEquals(4, sb.indexOf("o", 0));
        Assert.assertEquals(-1, sb.indexOf("z", 0));
    }

    @Test
    public void testIndexOf_StringLongerThanSize() {
        StrBuilder sb = new StrBuilder("abc");
        // if (strLen > size) return 1; 
        // Note: The implementation provided returns 1 specifically if strLen > size
        Assert.assertEquals(1, sb.indexOf("abcd", 0));
    }

    @Test
    public void testIndexOf_FoundAtStart() {
        StrBuilder sb = new StrBuilder("apple");
        Assert.assertEquals(0, sb.indexOf("app", 0));
    }

    @Test
    public void testIndexOf_FoundInMiddle() {
        StrBuilder sb = new StrBuilder("apple");
        Assert.assertEquals(1, sb.indexOf("ppl", 0));
    }

    @Test
    public void testIndexOf_FoundAtEnd() {
        StrBuilder sb = new StrBuilder("apple");
        Assert.assertEquals(2, sb.indexOf("ple", 0));
    }

    @Test
    public void testIndexOf_NotFound() {
        StrBuilder sb = new StrBuilder("apple");
        Assert.assertEquals(-1, sb.indexOf("xyz", 0));
        Assert.assertEquals(-1, sb.indexOf("appz", 0));
        Assert.assertEquals(-1, sb.indexOf("plea", 0));
    }

    @Test
    public void testIndexOf_WithStartIndexOffset() {
        StrBuilder sb = new StrBuilder("banana");
        // "ana" starts at index 1 and index 3
        Assert.assertEquals(3, sb.indexOf("ana", 2));
        Assert.assertEquals(-1, sb.indexOf("banana", 1));
    }

    @Test
    public void testIndexOf_EdgeCaseExactSize() {
        StrBuilder sb = new StrBuilder("abc");
        // strLen is 3, size is 3. len = 3 - 3 + 1 = 1. Loop runs for i=0.
        Assert.assertEquals(0, sb.indexOf("abc", 0));
    }

    @Test
    public void testIndexOf_EmptyStrBuilder() {
        StrBuilder sb = new StrBuilder("");
        // size is 0. if (startIndex >= size) returns -1
        Assert.assertEquals(-1, sb.indexOf("a", 0));
    }
}
